    schema: {"svg":"<svg viewBox=\"0 0 320 226\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\" fill=\"currentColor\" font-size=\"9\"><text x=\"78\" y=\"14\" text-anchor=\"middle\">ROUGE</text><text x=\"242\" y=\"14\" text-anchor=\"middle\">BLANC</text><rect x=\"10\" y=\"22\" width=\"136\" height=\"30\" rx=\"4\" fill-opacity=\"0.09\" stroke=\"currentColor\" stroke-opacity=\"0.55\" stroke-width=\"1\"/><text x=\"78\" y=\"41\" text-anchor=\"middle\" font-weight=\"bold\">éraflage</text><line x1=\"78\" y1=\"52\" x2=\"78\" y2=\"57\" stroke=\"currentColor\" stroke-opacity=\"0.55\" stroke-width=\"1\"/><polygon points=\"78,62 75,56 81,56\" fill-opacity=\"0.6\"/><rect x=\"10\" y=\"62\" width=\"136\" height=\"30\" rx=\"4\" fill-opacity=\"0.09\" stroke=\"currentColor\" stroke-opacity=\"0.55\" stroke-width=\"1\"/><text x=\"78\" y=\"75\" text-anchor=\"middle\">foulage</text><text x=\"78\" y=\"86\" text-anchor=\"middle\" fill-opacity=\"0.85\">souvent</text><line x1=\"78\" y1=\"92\" x2=\"78\" y2=\"97\" stroke=\"currentColor\" stroke-opacity=\"0.55\" stroke-width=\"1\"/><polygon points=\"78,102 75,96 81,96\" fill-opacity=\"0.6\"/><rect x=\"10\" y=\"102\" width=\"136\" height=\"30\" rx=\"4\" fill-opacity=\"0.09\" stroke=\"currentColor\" stroke-opacity=\"0.55\" stroke-width=\"1\"/><text x=\"78\" y=\"115\" text-anchor=\"middle\" font-weight=\"bold\">cuvaison</text><text x=\"78\" y=\"126\" text-anchor=\"middle\" fill-opacity=\"0.85\">macération sur les peaux</text><line x1=\"78\" y1=\"132\" x2=\"78\" y2=\"137\" stroke=\"currentColor\" stroke-opacity=\"0.55\" stroke-width=\"1\"/><polygon points=\"78,142 75,136 81,136\" fill-opacity=\"0.6\"/><rect x=\"10\" y=\"142\" width=\"136\" height=\"30\" rx=\"4\" fill-opacity=\"0.09\" stroke=\"currentColor\" stroke-opacity=\"0.55\" stroke-width=\"1\"/><text x=\"78\" y=\"155\" text-anchor=\"middle\" font-weight=\"bold\">écoulage</text><text x=\"78\" y=\"166\" text-anchor=\"middle\" fill-opacity=\"0.85\">vin de goutte</text><line x1=\"78\" y1=\"172\" x2=\"78\" y2=\"177\" stroke=\"currentColor\" stroke-opacity=\"0.55\" stroke-width=\"1\"/><polygon points=\"78,182 75,176 81,176\" fill-opacity=\"0.6\"/><rect x=\"10\" y=\"182\" width=\"136\" height=\"30\" rx=\"4\" fill-opacity=\"0.09\" stroke=\"currentColor\" stroke-opacity=\"0.55\" stroke-width=\"1\"/><text x=\"78\" y=\"195\" text-anchor=\"middle\">pressurage</text><text x=\"78\" y=\"206\" text-anchor=\"middle\" fill-opacity=\"0.85\">vin de presse</text><rect x=\"174\" y=\"22\" width=\"136\" height=\"30\" rx=\"4\" fill-opacity=\"0.09\" stroke=\"currentColor\" stroke-opacity=\"0.55\" stroke-width=\"1\"/><text x=\"242\" y=\"35\" text-anchor=\"middle\">pressurage</text><text x=\"242\" y=\"46\" text-anchor=\"middle\" fill-opacity=\"0.85\">directement, sans macération</text><line x1=\"242\" y1=\"52\" x2=\"242\" y2=\"57\" stroke=\"currentColor\" stroke-opacity=\"0.55\" stroke-width=\"1\"/><polygon points=\"242,62 239,56 245,56\" fill-opacity=\"0.6\"/><rect x=\"174\" y=\"62\" width=\"136\" height=\"30\" rx=\"4\" fill-opacity=\"0.09\" stroke=\"currentColor\" stroke-opacity=\"0.55\" stroke-width=\"1\"/><text x=\"242\" y=\"75\" text-anchor=\"middle\" font-weight=\"bold\">débourbage</text><text x=\"242\" y=\"86\" text-anchor=\"middle\" fill-opacity=\"0.85\">dépôt des lies grossières</text><line x1=\"242\" y1=\"92\" x2=\"242\" y2=\"97\" stroke=\"currentColor\" stroke-opacity=\"0.55\" stroke-width=\"1\"/><polygon points=\"242,102 239,96 245,96\" fill-opacity=\"0.6\"/><rect x=\"174\" y=\"102\" width=\"136\" height=\"30\" rx=\"4\" fill-opacity=\"0.09\" stroke=\"currentColor\" stroke-opacity=\"0.55\" stroke-width=\"1\"/><text x=\"242\" y=\"115\" text-anchor=\"middle\" font-weight=\"bold\">fermentation</text><text x=\"242\" y=\"126\" text-anchor=\"middle\" fill-opacity=\"0.85\">sans les peaux</text><line x1=\"160\" y1=\"22\" x2=\"160\" y2=\"206\" stroke=\"currentColor\" stroke-opacity=\"0.25\" stroke-width=\"1\"/><text x=\"242\" y=\"152\" text-anchor=\"middle\" fill-opacity=\"0.8\">puis, pour tous les vins :</text><text x=\"242\" y=\"164\" text-anchor=\"middle\" fill-opacity=\"0.8\">élevage, collage,</text><text x=\"242\" y=\"176\" text-anchor=\"middle\" fill-opacity=\"0.8\">filtration, mise</text><text x=\"242\" y=\"188\" text-anchor=\"middle\" fill-opacity=\"0.8\">en bouteille</text></svg>","legende":"Deux colonnes parallèles : les étapes du rouge et celles du blanc, jusqu’à la fermentation.","src":"Schéma original, d’après Lepeltier, Mille Vignes, p. 232-233"},
    cours: {"lede":"Rouge et blanc partagent presque les mêmes gestes, dans un ordre différent. La seule vraie question : les peaux fermentent-elles avec le jus, ou non ?","frise":null,"essentiel":"En rouge on macère d’abord et on presse ensuite ; en blanc on presse d’abord et on fait fermenter ensuite, sans les peaux.","sections":[{"h":"Deux ordres, un seul pivot","blocs":[{"imp":"essentiel","txt":"Le pivot est le moment où le jus quitte les peaux : après la cuvaison pour le rouge, avant la fermentation pour le blanc."},{"imp":"important","txt":"En rouge, la vendange est triée, éraflée, souvent foulée, puis encuvée : le moût fermente et macère sur ses peaux. On écoule ensuite le vin de goutte, puis on presse le marc : le vin de presse est, selon le livre, plus riche en polyphénols."},{"imp":"important","txt":"En blanc, la vendange est pressée directement, puis le moût pressé est débourbé : les lies grossières se déposent sous l’effet du froid, d’après le livre. La fermentation se fait ensuite sans les peaux."}],"table":{"caption":"Rouge et blanc, étape par étape","head":["Étape","Rouge","Blanc"],"rows":[{"imp":"essentiel","cells":["Avant la cuve","Tri, éraflage, foulage (souvent)","Pressurage direct de la vendange"]},{"imp":"essentiel","cells":["Contact avec les peaux","Oui : cuvaison, macération","Non"]},{"imp":"important","cells":["Séparation du jus","Écoulage, puis pressurage du marc","Pressurage direct, avant la fermentation"]},{"imp":"important","cells":["Débourbage","Non","Oui, avant la fermentation"]},{"imp":"essentiel","cells":["Fermentation","Avec les peaux","Sur jus clair, sans les peaux"]}]}},{"h":"Ce qui est commun","blocs":[{"imp":"utile","txt":"À partir de la fermentation, élevage, collage, filtration et mise en bouteille sont les mêmes pour tous les vins."}],"table":null}],"synthese":[{"imp":"essentiel","txt":"Rouge : éraflage, foulage, cuvaison, écoulage, pressurage."},{"imp":"essentiel","txt":"Blanc : pressurage, débourbage, fermentation sans peaux."},{"imp":"important","txt":"La différence tient au contact avec les peaux : macération pour le rouge, jus clair pour le blanc."},{"imp":"utile","txt":"À un client : un blanc se presse avant de fermenter, un rouge fermente avant d’être pressé."}],"src":"Mille Vignes, P. Lepeltier, p. 232-233. Cf. Mille Vignes, p. 232-233."},
